## Dos sistemas de módulos en JavaScript

JavaScript tiene dos sistemas de módulos que coexisten: **ESM** (ES Modules, el estándar moderno) y **CommonJS** (el sistema de Node.js original). Entender sus diferencias te permite trabajar en cualquier entorno.

---

## Sintaxis: la diferencia más visible

```javascript
// ── ESM (ES Modules) ───────────────────────────────
// Exportar:
export const PI = 3.14;
export function sumar(a, b) { return a + b; }
export default class Calculadora {}

// Importar:
import { sumar, PI } from './matematicas.js';
import Calculadora from './calculadora.js';
import * as Mat from './matematicas.js';

// ── CommonJS (CJS) ─────────────────────────────────
// Exportar:
const PI = 3.14;
function sumar(a, b) { return a + b; }
class Calculadora {}

module.exports = { PI, sumar };
// O:
module.exports = Calculadora; // Export principal
// O:
exports.PI = 3.14;           // Equivale a agregar propiedad

// Importar:
const { sumar, PI } = require('./matematicas');
const Calculadora = require('./calculadora');
```

---

## Carga: estática vs dinámica

Esta es la diferencia más importante a nivel de comportamiento:

```javascript
// ESM — carga ESTÁTICA (se resuelve antes de ejecutar)
// El motor analiza todos los imports ANTES de correr cualquier código
import { sumar } from './matematicas.js'; // Resuelto en tiempo de compilación

// Consecuencias:
// ✅ Tree shaking posible (el bundler sabe qué se usa)
// ✅ Errores de import detectados antes de ejecutar
// ❌ No puedes usar import() dentro de if (usa el import() dinámico)

// CJS — carga DINÁMICA (se ejecuta en tiempo de ejecución)
const modulo = require('./matematicas'); // Se ejecuta cuando llega esta línea

// Consecuencias:
// ✅ Puedes hacer require() condicional
if (process.env.NODE_ENV === 'test') {
  const mock = require('./matematicas-mock');
}
// ❌ Tree shaking difícil (el bundler no sabe qué se usará)
// ❌ Errores de require detectados solo al ejecutar esa línea
```

---

## Live bindings vs copias

```javascript
// ── ESM: Live bindings ─────────────────────────────
// contador.mjs
export let count = 0;
export function incrementar() { count++; }

// main.mjs
import { count, incrementar } from './contador.mjs';
console.log(count); // 0
incrementar();
console.log(count); // 1 ← ¡Ve el cambio!
// count es una referencia viva al valor en el módulo original

// ── CJS: Copias ────────────────────────────────────
// contador.js
let count = 0;
function incrementar() { count++; }
module.exports = { count, incrementar };

// main.js
const { count, incrementar } = require('./contador');
console.log(count); // 0
incrementar();
console.log(count); // 0 ← No ve el cambio (es una copia)
// Para ver el cambio: require('./contador').count (re-accede al objeto)
```

---

## Scope y modo estricto

```javascript
// ESM — siempre en strict mode, scope de módulo
// No necesitas 'use strict' — ya está activo
this === undefined; // true (en el top-level de un módulo ESM)

// Variables no son globales:
const local = 'solo en este módulo';
// window.local === undefined en browser

// CJS — NO es strict mode por defecto, scope de función
// (el código del módulo se envuelve en una función internamente)
this === module.exports; // true en el top-level de CJS

var global = 'atención: esto puede filtrar al scope global en algunos entornos';
```

---

## Variables especiales: `__dirname` y `__filename`

```javascript
// CJS — disponibles de forma nativa:
console.log(__dirname);  // /home/usuario/proyecto/src
console.log(__filename); // /home/usuario/proyecto/src/app.js

// ESM — NO existen, pero puedes recrearlas:
import { fileURLToPath } from 'url';
import { dirname } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// O usando import.meta.url directamente:
console.log(import.meta.url); // file:///home/usuario/proyecto/src/app.mjs
```

---

## Identificar el sistema de módulos

```json
// package.json
{
  "type": "module"    // → todos los .js son tratados como ESM
  // "type": "commonjs" → todos los .js son CJS (es el default)
}
```

```
Extensiones como pista:
.mjs → siempre ESM
.cjs → siempre CJS
.js  → depende del "type" en package.json
```

---

## Interop: usar CJS desde ESM y viceversa

```javascript
// ESM importando CJS — funciona con sintaxis default:
import miModuloCJS from './modulo.cjs';
// El module.exports se convierte en el default import
// Los named imports desde CJS son experimentales/limitados

// CJS importando ESM — NO funciona con require():
// require('./modulo.mjs') → ERROR
// Solución: dynamic import() dentro de async function:
async function cargar() {
  const { sumar } = await import('./modulo.mjs');
  return sumar(1, 2);
}
```

---

## Resumen comparativo

| Característica | ESM | CommonJS |
|---|---|---|
| Sintaxis | `import/export` | `require/module.exports` |
| Carga | Estática (compile-time) | Dinámica (runtime) |
| Bindings | Live (referencias vivas) | Copias |
| Strict mode | Siempre activo | No por defecto |
| `__dirname` | No (usar `import.meta`) | Sí |
| Tree shaking | Nativo | Difícil |
| Entorno | Browser + Node 12+ | Node.js |
| Async top-level | Soportado | No |
| Extensión típica | `.mjs` o `.js` (con `"type":"module"`) | `.cjs` o `.js` |

examples.code:
// Simular el comportamiento de 'live bindings' vs 'copias'
// ESM usa live bindings: el importador ve cambios en el valor original

// Simulamos un módulo contador (como si fuera ESM)
const modulo = (() => {
  let _count = 0;

  // En ESM real, el importador accede directamente a _count
  // Lo simulamos con un getter
  return {
    get count() { return _count; },  // Live binding simulation
    incrementar() { _count++; },
    resetear() { _count = 0; },
  };
})();

// Importador
const { count: copia } = { count: modulo.count }; // CJS: copia del valor
const liveCount = () => modulo.count;              // ESM: acceso vivo

console.log('Antes:', copia, liveCount()); // 0, 0
modulo.incrementar();
modulo.incrementar();
console.log('Después:', copia, liveCount()); // 0, 2 — ¡la copia no cambia!

// Simular require() con caché (como Node.js internamente)
const _cache = {};

function require(nombreModulo) {
  if (_cache[nombreModulo]) {
    console.log(`[cache hit] ${nombreModulo}`);
    return _cache[nombreModulo];
  }

  // Simula la 'ejecución' del módulo
  const modulos = {
    'matematicas': { sumar: (a,b) => a+b, PI: 3.14 },
    'strings': { mayusculas: s => s.toUpperCase() },
  };

  const exports = modulos[nombreModulo];
  if (!exports) throw new Error(`Cannot find module '${nombreModulo}'`);

  _cache[nombreModulo] = exports;
  return exports;
}

const mat1 = require('matematicas'); // Ejecuta el módulo
const mat2 = require('matematicas'); // Devuelve del caché

console.log(mat1 === mat2); // true — misma referencia
console.log(mat1.sumar(2, 3)); // 5

exercises.prompt:
Dado el siguiente código, determina si es ESM o CommonJS y explica las variables de clasificación:

```javascript
// Fragmento A:
const { readFile } = require('fs');
module.exports = { leer: readFile };

// Fragmento B:
import { readFile } from 'fs';
export function leer(path) { return readFile(path); }
```

Guarda:
- `sistemaA = 'CommonJS'`
- `sistemaB = 'ESM'`
- `usaRequire = 'CommonJS'` (¿qué sistema usa `require()`?)
- `usaLiveBindings = 'ESM'` (¿qué sistema tiene live bindings?)
- `tieneTreeShaking = 'ESM'` (¿qué sistema soporta tree shaking nativo?)

