// Simula ESM con live binding
const esmContador = (() => {
  let _n = 0;
  return {
    get valor() { return _n; },
    incrementar() { _n++; },
  };
})();

// Simula CJS con copia
const { valor: cjsCopia } = esmContador; // Copia el valor en este momento

const antes = esmContador.valor; // 0

esmContador.incrementar();
esmContador.incrementar();
esmContador.incrementar();

const despues = esmContador.valor;       // 3 (live binding)
const cjsCopiaDespues = cjsCopia;        // 0 (copia no cambia)

console.log('ESM antes:', antes, '→ después:', despues);
console.log('CJS copia:', cjsCopia, '→ sigue siendo:', cjsCopiaDespues);

const registry = {
  'utils/math': { sumar: (a, b) => a + b, PI: 3.14159 },
  'utils/string': { trim: s => s.trim(), upper: s => s.toUpperCase() },
  'config': { version: '1.0.0', debug: false },
};

function crearSistemaModulos() {
  const cache = {};

  return {
    require(nombre) {
      if (cache[nombre]) return cache[nombre];
      if (!registry[nombre]) throw new Error('Cannot find module: ' + nombre);
      cache[nombre] = registry[nombre];
      return cache[nombre];
    },
    cacheSize() {
      return Object.keys(cache).length;
    },
  };
}

const sistema = crearSistemaModulos();

const math1 = sistema.require('utils/math');
const math2 = sistema.require('utils/math'); // Cache hit
const config = sistema.require('config');

const mismaInstancia = math1 === math2;
const version = config.version;
const tamanoCache = sistema.cacheSize(); // 2: math + config

let errorAtrapado = false;
try {
  sistema.require('no-existe');
} catch (e) {
  errorAtrapado = e.message.includes('Cannot find module');
}

console.log('Misma instancia:', mismaInstancia);
console.log('Versión:', version);
console.log('Caché size:', tamanoCache);
console.log('Error atrapado:', errorAtrapado);
